package com.rwi.myrepublic.astri;import java.io.IOException;import java.io.InputStream;import java.util.Properties;public class AstriConfig{private static AstriConfig instance;private Properties props;private AstriConfig(){props=new Properties();try(InputStream in=getClass().getClassLoader().getResourceAsStream("astri_config.properties")){if(in!=null){props.load(in);}}catch(IOException e){System.err.println("Warning: Could not load astri_config.properties, using defaults");}}public static
AstriConfig getInstance(){if(instance==null){synchronized(AstriConfig.class){if(instance==null){instance=new AstriConfig();}}}return instance;}public String getApiBaseUrl(){return props.getProperty("astri.api.base.url", "");}public String getDmBaseUrl(){return props.getProperty("astri.dm.base.url", "");}public String getUsername(){return props.getProperty("astri.username", "");}public String getPassword(){return props.getProperty("astri.password", "");}public long getRequestTimeout(){return
Long.parseLong(props.getProperty("astri.timeout.request", "30000"));}public long getConnectionTimeout(){return Long.parseLong(props.getProperty("astri.timeout.connection", "10000"));}public String getDownloadDir(){String smallworldGis=System.getenv("SMALLWORLD_GIS");if(smallworldGis!=null&&!smallworldGis.isEmpty()){java.io.File gisDir=new java.io.File(smallworldGis);java.io.File parentDir=gisDir.getParentFile();if(parentDir!=null){return parentDir.getAbsolutePath()+ "/kml_files";}return
smallworldGis+ "/kml_files";}return props.getProperty("astri.download.dir", "downloads");}}